package org.example;
import java.nio.file.*;import java.util.*;
/** Bounded one-host actual-APK heap diagnostics; no full APK report. */
public final class FanqieHolderTrace {
 public static void main(String[]args)throws Exception{long d=System.nanoTime()+300_000_000_000L;Path p=Path.of(args[0]);ApkInventory a=ApkInventory.read(p);CapabilityIndex i=new CapabilityIndex();i.read(p,d);System.out.println("INDEX_COMPLETE seconds="+(300_000_000_000L-(d-System.nanoTime()))/1e9);d=System.nanoTime()+60_000_000_000L;CapabilityEngine e=new CapabilityEngine(i,a,d);var state=e.beginActivity("com.dragon.read.hybrid.webview.WebViewActivity");Set<String> seen=new HashSet<>();e.checkpoint=()->{var h=e.currentHost;if(h==null)return;for(var x:h.heap.entrySet())if(x.getKey().contains("webview/base/a;->")||x.getKey().contains("SwipeRefreshWebView;->M:")){String s="HEAP "+x;if(seen.add(s))System.out.println(s);}};long stop=System.nanoTime()+15_000_000_000L;while(!state.done&&System.nanoTime()<stop)e.advanceActivity(state,50_000_000L,50);System.out.println("STATE jobs="+state.jobs+" done="+state.done+" pending="+state.host.queue.size());System.out.println("DIAG "+state.host.gaps);for(var f:state.host.facts.values())if("callback".equals(f.get("kind"))&&String.valueOf(f.get("implementation")).contains("SwipeRefreshWebView$c"))System.out.println("QFACT "+f);}
}
